#!/usr/bin/env python3
"""Read selective component links from the retained candidate passages.

Run: PYTHONDONTWRITEBYTECODE=1 python scripts/link_roles.py [--check]
The explicit CURATION ledger records a passage reading for every candidate.
--export-readings writes the review packet to tmp/refresh/role_candidates.json.
No relation label alone determines whether an earlier method is a component.
"""
import argparse
import csv
import hashlib
import json
from collections import Counter
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
FIELDS = 'link_id later_method earlier_method component_role builds_on role_statement'.split()
RELATIONS = set('uses extends special_case_of contains_special_case combines shares_structure_not_equivalent derivable_under_conditions inspired_by'.split())
COMPONENT = set('model prior likelihood fitting_algorithm building_block generalizes output theory'.split())
OTHER = set('similar inspired compared tool_step alternative mention'.split())


def read(name):
    with (ROOT / name).open(newline='', encoding='utf-8') as f:
        return list(csv.DictReader(f, delimiter='\t'))


def digest(text):
    return hashlib.sha256(text.encode()).hexdigest()


def candidates():
    contexts = {r['context_id']: r for r in read('tables/citation_contexts.tsv')}
    claims = {r['claim_id']: r for r in read('tables/claims.tsv')}
    seeds = {r['paper_id']: r for r in read('seed/seed_list.tsv')}
    methods = {}
    for r in read('tables/methods.tsv'):
        methods.setdefault(r['method_id'], []).append(r)
    nodes = {r['node_id']: r for r in read('tables/citation_nodes.tsv')}
    def year(mid):
        base = mid.split('.')[0]
        if base in seeds:
            return seeds[base].get('year', 'NA')
        years = [seeds.get(r['paper_id'], {}).get('year', 'NA') for r in methods.get(base, [])]
        numeric = [int(y) for y in years if y.isdigit()]
        return str(min(numeric)) if numeric else nodes.get(base, {}).get('year', 'NA')
    output = []
    def add(link_id, later, earlier, passage, source, row, relation):
        output.append(dict(link_id=link_id, later_method=later, earlier_method=earlier,
            later_year=year(later), earlier_year=year(earlier), passage=passage,
            passage_sha256=digest(passage), source=source, source_row=row,
            relation=relation))
    for r in read('tables/context_links.tsv'):
        if r['relation'] in RELATIONS and r['citing_method_id'] != 'NA':
            c = contexts[r['context_id']]
            add(r['context_id'], r['citing_method_id'], r['cited_node_id'],
                c['sentence'], 'context_links', dict(r, context=c), r['relation'])
            output[-1]['later_year'] = seeds.get(c['citing_paper'], {}).get('year', 'NA')
            output[-1]['earlier_year'] = c['cited_year']
    for r in read('tables/edge_links.tsv'):
        if r['verdict'] in {'stated', 'stated_other_type'}:
            typ = r['stated_type'] if r['stated_type'] != 'NA' else r['type']
            later, earlier = r['from_id'], r['to_id']
            if typ == 'special_case_of':
                later, earlier = earlier, later
            add(r['edge_id'], later, earlier, r['link_span'], 'edge_links', r, typ)
    for i, r in enumerate(read('tables/parents.tsv')):
        first = r['supporting_claims'].split('; ')[0]
        if first not in claims:
            raise ValueError('Missing first supporting claim for par:' + str(i))
        add('par:' + str(i), r['child_method_id'], r['parent_id'],
            claims[first]['span'], 'parents', dict(r, claim=claims[first]), r['proposed_type'])
    ids = [r['link_id'] for r in output]
    if len(set(ids)) != len(ids):
        raise ValueError('Candidate link IDs are not unique')
    return output


def materialize():
    source = candidates()
    expected = {r['link_id'] for r in source}
    if set(CURATION) != expected:
        raise ValueError('Readings coverage differs: missing=' + str(sorted(expected-set(CURATION)))
                         + '; stale=' + str(sorted(set(CURATION)-expected)))
    rows = []
    for r in source:
        d = CURATION[r['link_id']]
        if d['passage_sha256'] != r['passage_sha256']:
            raise ValueError('Passage changed; renew reading: ' + r['link_id'])
        role = d['component_role']
        if role not in COMPONENT | OTHER:
            raise ValueError('Invalid component role: ' + r['link_id'])
        expected_build = 'yes' if role in COMPONENT and d['about_later_method'] else 'no'
        if d['builds_on'] != expected_build:
            raise ValueError('Builds-on rule violated: ' + r['link_id'])
        later = d.get('later_method', r['later_method'])
        earlier = d.get('earlier_method', r['earlier_method'])
        if {later, earlier} != {r['later_method'], r['earlier_method']}:
            raise ValueError('Reading introduced an ID absent from its source: ' + r['link_id'])
        if not 0 < len(d['role_statement'].split()) <= 20:
            raise ValueError('Statement must contain 1 to 20 words: ' + r['link_id'])
        # A later restriction of an earlier general method is similarity, not
        # evidence that the earlier general method builds on its newer special case.
        if role == 'generalizes':
            ly, ey = r['later_year'], r['earlier_year']
            if ly.isdigit() and ey.isdigit() and int(ly) < int(ey):
                raise ValueError('Generalization direction conflicts with publication years: ' + r['link_id'])
        rows.append(dict(link_id=r['link_id'], later_method=later, earlier_method=earlier,
            component_role=role, builds_on=d['builds_on'], role_statement=d['role_statement']))
    return rows


def run(check=False):
    rows = materialize()
    target = ROOT / 'tables/link_roles.tsv'
    if check:
        actual = read('tables/link_roles.tsv')
        if actual != rows:
            raise ValueError('Link-role output differs from explicit passage readings')
    else:
        with target.open('w', newline='', encoding='utf-8') as f:
            out = csv.DictWriter(f, fieldnames=FIELDS, delimiter='\t', lineterminator='\n')
            out.writeheader()
            out.writerows(rows)
    print(json.dumps({'rows': len(rows), 'component_role': dict(sorted(Counter(r['component_role'] for r in rows).items())),
        'builds_on': dict(sorted(Counter(r['builds_on'] for r in rows).items())), 'check': 'PASS'}, sort_keys=True))


